// Solstice - Render layer: the paper material.

#include "Render/SolsticeCelMaterial.h"

#include "Materials/Material.h"
#include "Materials/MaterialInstanceDynamic.h"
#include "ProceduralMeshComponent.h"
#include "Solstice.h"

namespace Solstice
{
	namespace
	{
		/** Master material assets, generated by SolsticeEditor on a fresh checkout. */
		const TCHAR* CelAssetPath = TEXT("/Game/Core/M_Cel.M_Cel");
		const TCHAR* InkAssetPath = TEXT("/Game/Core/M_Ink.M_Ink");

		/** Engine fallbacks so the realm still renders before the assets exist. */
		const TCHAR* CelFallbackPath = TEXT("/Engine/EngineDebugMaterials/VertexColorViewMode_ColorOnly.VertexColorViewMode_ColorOnly");
		const TCHAR* InkFallbackPath = TEXT("/Engine/EngineDebugMaterials/BlackUnlitMaterial.BlackUnlitMaterial");

		// ------------------------------------------------------------------
		// Cel material tuning (docs/art/art.md SS2.1).
		// The material is unlit and paints its own three bands; everything the lighting model
		// would have supplied is a colour here instead, which is the only way the band edges stay
		// hard through post processing. This block is the whole "how does the world look under
		// this sky" recipe, so a look tune is one file read.
		// ------------------------------------------------------------------

		/** Kelvin -> linear conversion window, and the sRGB decode gamma of the palette. */
		constexpr float KelvinClampMin = 1000.0f;
		constexpr float KelvinClampMax = 12000.0f;
		constexpr float SrgbToLinearGamma = 2.2f;

		/** Sun altitude window used for tinting, and the ramp that turns it into "daylight". */
		constexpr float SkyAltitudeClampMinDeg = -12.0f;
		constexpr float SkyAltitudeClampMaxDeg = 90.0f;
		constexpr float DaylightAltitudeFloorDeg = -5.0f;
		constexpr float DaylightAltitudeSpanDeg = 12.0f;

		/** Overcast grey the lit band is pulled toward. */
		const FLinearColor CloudGrey(0.62f, 0.64f, 0.67f);
		/** Cool ambient for the shadow band; SS2.1 asks for a lifted, blue-violet shadow. */
		const FLinearColor ShadowCool(0.30f, 0.34f, 0.50f);
		const FLinearColor ShadowOvercast(0.40f, 0.42f, 0.50f);
		/** Chaos (unpainted) leans chalky and flat so the first colour reads as a change. */
		const FLinearColor ChaosLitTint(0.86f, 0.85f, 0.82f);
		const FLinearColor ChaosShadowTint(0.36f, 0.36f, 0.38f);

		/** Where the middle band sits between shadow and lit, and the lighting mix weights. */
		constexpr float MidBandMix = 0.60f;
		constexpr float SunGainFloor = 0.55f;
		constexpr float SunGainScale = 0.55f;
		constexpr float CloudMixStrength = 0.62f;
		constexpr float NightDimFloor = 0.16f;
		constexpr float ShadowCloudStrength = 0.8f;
		constexpr float ShadowDayFloor = 0.55f;
		constexpr float ChaosLitStrength = 0.35f;
		constexpr float ChaosShadowStrength = 0.45f;

		/**
		 * Band edges, straight from art.md SS2.1: below 0.30 the surface takes the shadow colour,
		 * above 0.62 the lit one. Pushed onto the material instance rather than baked into the
		 * asset so retuning them at the style gate costs a rebuild of nothing.
		 */
		constexpr float BandLow = 0.30f;
		constexpr float BandHigh = 0.62f;

		/** Tanner Helland's approximation, mapped to linear so the emissive term behaves. */
		FLinearColor KelvinToLinearColour(float Kelvin)
		{
			const float T = FMath::Clamp(Kelvin, KelvinClampMin, KelvinClampMax) / 100.0f;
			float R;
			float G;
			float B;
			if (T <= 66.0f)
			{
				R = 255.0f;
				G = 99.4708025861f * FMath::Loge(T) - 161.1195681661f;
				B = (T <= 19.0f) ? 0.0f : (138.5177312231f * FMath::Loge(T - 10.0f) - 305.0447927307f);
			}
			else
			{
				R = 329.698727446f * FMath::Pow(T - 60.0f, -0.1332047592f);
				G = 288.1221695283f * FMath::Pow(T - 60.0f, -0.0755148492f);
				B = 255.0f;
			}
			auto ToLinear = [](float Srgb)
			{
				const float Normalised = FMath::Clamp(Srgb, 0.0f, 255.0f) / 255.0f;
				return FMath::Pow(Normalised, 2.2f);
			};
			return FLinearColor(ToLinear(R), ToLinear(G), ToLinear(B));
		}
	}

	FCelMaterialSet FCelMaterials::Set;
	bool FCelMaterials::bResolved = false;
	bool FCelMaterials::bBuildAttempted = false;
	TFunction<bool()> GBuildCelMaterials;

	void FCelMaterials::SetBuilder(TFunction<bool()> InBuilder)
	{
		GBuildCelMaterials = MoveTemp(InBuilder);
		bResolved = false;
		bBuildAttempted = false;
	}

	bool FCelMaterials::Ensure()
	{
		// Fast path. The second test matters: while a builder could still arrive we must not latch
		// onto the fallback materials, or a fresh checkout would keep the engine's unlit debug
		// material for the whole session.
		//
		// In an editor launch the builder is installed by FSolsticeEditorModule::StartupModule,
		// which is why this is written to tolerate the ordering either way round: whoever gets
		// here first wins, and the other one re-resolves.
		if (bResolved && Set.Cel && Set.Ink && (Set.bAuthored || bBuildAttempted))
		{
			return Set.bAuthored;
		}

		UMaterialInterface* Cel = LoadObject<UMaterialInterface>(nullptr, CelAssetPath);
		UMaterialInterface* Ink = LoadObject<UMaterialInterface>(nullptr, InkAssetPath);

		// Exactly one attempt per builder install. SetBuilder resets the flag, so a builder that
		// arrives late still gets its chance, but a builder that is still missing must not make us
		// re-run LoadObject every frame - that floods LogStreaming with FlushAsyncLoading.
		if (!bBuildAttempted)
		{
			bBuildAttempted = true;
			if (!GBuildCelMaterials)
			{
				// -game and cooked builds: SolsticeEditor is not loaded, so the only way to get
				// the masters is to have run "-run=SolsticeGenAssets" beforehand. If they are not
				// on disk we fall through to the engine debug materials below.
				UE_LOG(LogSolstice, Log, TEXT("paper: no builder installed (editor module absent)"));
			}
			else if (!Cel || !Ink)
			{
				// Fresh checkout: let the editor module write the assets, then look again.
				const bool bBuilt = GBuildCelMaterials();
				UE_LOG(LogSolstice, Log, TEXT("paper: builder returned %s"), bBuilt ? TEXT("true") : TEXT("false"));
				if (bBuilt)
				{
					Cel = Cel ? Cel : LoadObject<UMaterialInterface>(nullptr, CelAssetPath);
					Ink = Ink ? Ink : LoadObject<UMaterialInterface>(nullptr, InkAssetPath);
				}
			}
		}

		Set.bAuthored = (Cel != nullptr) && (Ink != nullptr);
		if (!Cel)
		{
			Cel = LoadObject<UMaterialInterface>(nullptr, CelFallbackPath);
		}
		if (!Ink)
		{
			Ink = LoadObject<UMaterialInterface>(nullptr, InkFallbackPath);
		}

		// Root everything we hand out. FCelMaterials is a plain static, so its raw pointers are
		// invisible to the GC: the MIDs are created in the transient package and would be collected
		// during the next map load, after which every ApplyToMesh/ApplySky reads freed memory
		// (observed as EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff).
		if (Set.Cel) { Set.Cel->RemoveFromRoot(); }
		if (Set.Ink) { Set.Ink->RemoveFromRoot(); }
		if (Set.CelMID) { Set.CelMID->RemoveFromRoot(); }
		if (Set.InkMID) { Set.InkMID->RemoveFromRoot(); }

		Set.Cel = Cel;
		Set.Ink = Ink;
		Set.CelMID = Cel ? UMaterialInstanceDynamic::Create(Cel, GetTransientPackage()) : nullptr;
		Set.InkMID = Ink ? UMaterialInstanceDynamic::Create(Ink, GetTransientPackage()) : nullptr;

		if (Set.Cel) { Set.Cel->AddToRoot(); }
		if (Set.Ink) { Set.Ink->AddToRoot(); }
		if (Set.CelMID) { Set.CelMID->AddToRoot(); }
		if (Set.InkMID) { Set.InkMID->AddToRoot(); }

		if (Set.CelMID)
		{
			Set.CelMID->SetScalarParameterValue(TEXT("BandLow"), BandLow);
			Set.CelMID->SetScalarParameterValue(TEXT("BandHigh"), BandHigh);
		}

		bResolved = true;
		UE_LOG(LogSolstice, Log, TEXT("paper: %s / %s -> %s"),
			Cel ? *Cel->GetPathName() : TEXT("none"),
			Ink ? *Ink->GetPathName() : TEXT("none"),
			Set.bAuthored ? TEXT("authored") : TEXT("fallback"));
		return Set.bAuthored;
	}

	void FCelMaterials::ApplySky(const FSkyState& Sky, bool bChaos)
	{
		Ensure();
		if (!Set.CelMID || !Set.bAuthored)
		{
			return;
		}

		const float Altitude = FMath::Clamp(Sky.SolarAltitudeDeg, SkyAltitudeClampMinDeg, SkyAltitudeClampMaxDeg);
		const float Daylight = FMath::Clamp(
			(Altitude - DaylightAltitudeFloorDeg) / DaylightAltitudeSpanDeg, 0.0f, 1.0f);

		const FLinearColor SunColour = KelvinToLinearColour(Sky.ColorTempK);
		const float Cloud = FMath::Clamp(Sky.CloudCover, 0.0f, 1.0f);

		// Lit band: sun colour, pulled toward an overcast grey by cloud, dimmed outside daytime.
		FLinearColor Lit = FMath::Lerp(
			SunColour * (SunGainFloor + SunGainScale * Sky.LightIntensity),
			CloudGrey,
			Cloud * CloudMixStrength);
		Lit *= FMath::Lerp(NightDimFloor, 1.0f, Daylight);

		// Shadow band: cool ambient, brighter when the sky is overcast. SS2.1 asks for a *lifted*
		// shadow - at least 45% of the lit band's lightness and shifted toward blue-violet - so
		// the dark side reads as a colour, never as a hole.
		FLinearColor Shadow = FMath::Lerp(ShadowCool, ShadowOvercast, Cloud * ShadowCloudStrength);
		Shadow *= FMath::Lerp(ShadowDayFloor, 1.0f, Daylight);

		if (bChaos)
		{
			// Unpainted paper: everything leans chalky and flat so the first colour reads as a change.
			Lit = FMath::Lerp(Lit, ChaosLitTint, ChaosLitStrength);
			Shadow = FMath::Lerp(Shadow, ChaosShadowTint, ChaosShadowStrength);
		}

		// The middle band is derived, not authored: it is the same light at a lower incidence, so
		// interpolating keeps dusk/overcast/night from drifting apart across the three stops.
		const FLinearColor Mid = FMath::Lerp(Shadow, Lit, MidBandMix);

		// The bands are thresholds on dot(VertexNormalWS, SunDirection). The direction has to be
		// pushed from here: without it the bands stay frozen on the asset's default vector and the
		// world never turns with the sun.
		const float SunAltRad = FMath::DegreesToRadians(Altitude);
		const float SunAzRad = FMath::DegreesToRadians(Sky.SunAzimuthDeg);
		const FVector SunDirection(
			FMath::Cos(SunAltRad) * FMath::Cos(SunAzRad),
			FMath::Cos(SunAltRad) * FMath::Sin(SunAzRad),
			FMath::Sin(SunAltRad));

		Set.CelMID->SetVectorParameterValue(TEXT("SunDirection"), FLinearColor(SunDirection));
		Set.CelMID->SetVectorParameterValue(TEXT("LitTint"), Lit);
		Set.CelMID->SetVectorParameterValue(TEXT("MidTint"), Mid);
		Set.CelMID->SetVectorParameterValue(TEXT("ShadowTint"), Shadow);
	}

	void FCelMaterials::ApplyToMesh(UProceduralMeshComponent* Mesh)
	{
		if (!Mesh)
		{
			return;
		}
		Ensure();
		if (Set.CelMID)
		{
			Mesh->SetMaterial(0, Set.CelMID);
		}
		if (Set.InkMID)
		{
			Mesh->SetMaterial(1, Set.InkMID);
		}
	}
}
